-- Optional isolated-test clock. NULL in all deployed environments.
-- Only the explicitly enabled loopback local-admin action may set it.
CREATE TABLE installer_test_clock(id INTEGER PRIMARY KEY CHECK(id=1),fixed_at TEXT CHECK(fixed_at IS NULL OR julianday(fixed_at) IS NOT NULL));
INSERT INTO installer_test_clock(id,fixed_at) VALUES(1,NULL);
DROP TRIGGER installer_delivery_guard;
CREATE TRIGGER installer_delivery_guard BEFORE INSERT ON lead_recipient_deliveries WHEN NEW.delivery_channel='portal' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leads l JOIN solar_company_partners p ON p.id=NEW.partner_id JOIN installer_platform_settings s ON s.id=1 WHERE l.id=NEW.lead_id AND l.quality_score>=COALESCE(json_extract(s.config_json,'$.minimumQuality'),4) AND (COALESCE(json_extract(s.config_json,'$.ownerRequired'),1)=0 OR l.ownership_status='owner') AND l.air_conditioner_count>=COALESCE(json_extract(s.config_json,'$.minimumAcUnits'),4) AND l.quality_score>=COALESCE(json_extract(p.accepted_lead_criteria_json,'$.minimumQuality'),1) AND (COALESCE(json_extract(p.accepted_lead_criteria_json,'$.ownerRequired'),0)=0 OR l.ownership_status='owner') AND l.air_conditioner_count>=COALESCE(json_extract(p.accepted_lead_criteria_json,'$.minimumAcUnits'),0) AND l.monthly_bill_thb>=COALESCE(json_extract(p.preferences_json,'$.minimumBill'),0) AND (json_extract(p.preferences_json,'$.propertyTypes') IS NULL OR EXISTS(SELECT 1 FROM json_each(p.preferences_json,'$.propertyTypes') WHERE value=l.property_type)) AND l.adult_confirmed_at IS NOT NULL AND l.privacy_notice_version_id=NEW.privacy_notice_version_id AND l.consent_version=NEW.consent_version AND json(NEW.fields_disclosed_json)=json(l.disclosed_fields_snapshot_json)) THEN RAISE(ABORT,'qualification or consent snapshot mismatch') END;
 SELECT CASE WHEN NEW.enquiry_id IS NULL OR NEW.available_at IS NULL OR NEW.claim_deadline IS NULL OR NEW.delivered_at<>NEW.available_at THEN RAISE(ABORT,'missing portal delivery facts') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_platform_settings WHERE id=1 AND json_extract(config_json,'$.collectionEnabled')=1 AND COALESCE(json_extract(config_json,'$.deliveryPaused'),1)=0 AND CAST(strftime('%H',COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours') AS INTEGER)>=COALESCE(json_extract(config_json,'$.startHour'),9) AND CAST(strftime('%H',COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours') AS INTEGER)<COALESCE(json_extract(config_json,'$.endHour'),17)) THEN RAISE(ABORT,'allocation disabled or outside delivery hours') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_enquiries e JOIN leads l ON l.id=e.lead_id WHERE e.id=NEW.enquiry_id AND e.lead_id=NEW.lead_id AND e.product=NEW.product AND e.verification_state='verified' AND e.qualification_state='eligible' AND e.duplicate_state IN('original','repeat') AND e.status IN('queued','partially-delivered','unmatched') AND e.suppressed_at IS NULL AND julianday(e.request_expires_at)>julianday(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now'))) AND l.suppressed=0 AND l.consent_withdrawn_at IS NULL AND l.deleted_at IS NULL AND l.archived_at IS NULL AND l.distribution_allowed=1 AND l.quote_contact_requested=1 AND l.third_party_disclosure_authorized_v2=1 AND l.consent_scope_v2='shared_residential_solar_referral' AND julianday(l.distribution_expires_at)>julianday(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')))) THEN RAISE(ABORT,'enquiry is not eligible') END;
 SELECT CASE WHEN NEW.product<>'shared_residential' THEN RAISE(ABORT,'exclusive delivery disabled') END;
 SELECT CASE WHEN (SELECT COUNT(DISTINCT partner_id) FROM lead_recipient_deliveries WHERE enquiry_id=NEW.enquiry_id)>=(SELECT MIN(3,recipient_limit) FROM installer_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'recipient limit reached') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM solar_company_partners p JOIN leads l ON l.id=NEW.lead_id JOIN installer_platform_settings s ON s.id=1 WHERE p.id=NEW.partner_id AND p.approval_status='approved' AND p.active=1 AND p.paused=0 AND p.contract_state='active' AND p.archived_at IS NULL AND (p.contract_effective_date IS NULL OR date(p.contract_effective_date)<=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours')) AND (p.contract_expiry_date IS NULL OR date(p.contract_expiry_date)>=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours')) AND p.terms_version=json_extract(s.config_json,'$.termsVersion') AND p.terms_accepted_at IS NOT NULL AND EXISTS(SELECT 1 FROM json_each(p.supported_products_json) WHERE value=NEW.product) AND (EXISTS(SELECT 1 FROM json_each(p.service_provinces_json) WHERE value=l.province) OR EXISTS(SELECT 1 FROM json_each(p.service_areas_json) WHERE value=l.province)) AND (SELECT COUNT(*) FROM lead_recipient_deliveries d WHERE d.partner_id=p.id AND d.delivery_channel='portal' AND date(d.available_at,'+7 hours')=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours'))<p.daily_limit AND (p.operational_capacity IS NULL OR (SELECT COUNT(*) FROM lead_recipient_deliveries d WHERE d.partner_id=p.id AND d.delivery_channel='portal' AND date(d.available_at,'+7 hours')=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours'))<p.operational_capacity)) THEN RAISE(ABORT,'company is not eligible') END;
 SELECT CASE WHEN NEW.credit_cost<>(SELECT COALESCE(json_extract(config_json,'$.sharedCredits'),2) FROM installer_platform_settings WHERE id=1) OR NEW.price_minor<>(SELECT COALESCE(json_extract(config_json,'$.sharedCredits'),2)*COALESCE(json_extract(config_json,'$.creditValueMinor'),20000) FROM installer_platform_settings WHERE id=1) THEN RAISE(ABORT,'incorrect price snapshot') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_credit_accounts WHERE company_id=NEW.partner_id AND debt=0 AND ((NEW.funding_source='trial' AND trial_remaining>=1) OR (NEW.funding_source='purchased' AND available>=NEW.credit_cost))) THEN RAISE(ABORT,'no funding available') END;
END;
DROP TRIGGER installer_contract_dates_guard;
CREATE TRIGGER installer_contract_dates_guard BEFORE INSERT ON lead_recipient_deliveries WHEN NEW.delivery_channel='portal' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM solar_company_partners WHERE id=NEW.partner_id AND contract_effective_date IS NOT NULL AND contract_expiry_date IS NOT NULL AND julianday(contract_effective_date) IS NOT NULL AND julianday(contract_expiry_date) IS NOT NULL AND date(contract_effective_date)<=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours') AND date(contract_expiry_date)>=date(COALESCE((SELECT fixed_at FROM installer_test_clock WHERE id=1),strftime('%Y-%m-%dT%H:%M:%fZ','now')),'+7 hours')) THEN RAISE(ABORT,'valid contract dates required') END;
END;
